//! Types shared with the frontend.
//!
//! The TypeScript bindings are generated by `ts-rs` into `src/bindings` when running `cargo test`.
//! Numeric fields are `u64` on the Rust side but `number` on the TypeScript side (sizes stay
//! well below 2^53 bytes).

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Names of the events emitted to the frontend.
pub const EVENT_PROGRESS: &str = "scan:progress";
pub const EVENT_DONE: &str = "scan:done";
pub const EVENT_FAILED: &str = "scan:failed";
pub const EVENT_APP_SIZE: &str = "apps:size";
pub const EVENT_APPS_DONE: &str = "apps:done";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "lowercase")]
#[ts(export)]
pub enum FileType {
    Video,
    Img,
    Doc,
    Code,
    Arch,
    Other,
}

impl FileType {
    pub const ALL: [FileType; 6] = [
        FileType::Video,
        FileType::Img,
        FileType::Doc,
        FileType::Code,
        FileType::Arch,
        FileType::Other,
    ];

    /// Position in the per-type vectors.
    pub fn index(self) -> usize {
        self as usize
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "lowercase")]
#[ts(export)]
pub enum NodeKind {
    Dir,
    File,
    /// Synthetic node that groups the files of a folder with many entries.
    Agg,
    /// Inaccessible folder (permission denied).
    Denied,
}

/// Bytes per file type.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, TS)]
#[ts(export)]
pub struct TypeBreakdown {
    #[ts(type = "number")]
    pub video: u64,
    #[ts(type = "number")]
    pub img: u64,
    #[ts(type = "number")]
    pub doc: u64,
    #[ts(type = "number")]
    pub code: u64,
    #[ts(type = "number")]
    pub arch: u64,
    #[ts(type = "number")]
    pub other: u64,
}

impl From<[u64; 6]> for TypeBreakdown {
    fn from(v: [u64; 6]) -> Self {
        TypeBreakdown {
            video: v[FileType::Video.index()],
            img: v[FileType::Img.index()],
            doc: v[FileType::Doc.index()],
            code: v[FileType::Code.index()],
            arch: v[FileType::Arch.index()],
            other: v[FileType::Other.index()],
        }
    }
}

/// Item of the folder tree. The frontend requests it level by level, as the user expands
/// folders: the full tree stays in memory on the Rust side.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Node {
    #[ts(type = "number")]
    pub id: u64,
    #[ts(type = "number | null")]
    pub parent_id: Option<u64>,
    /// Empty for aggregate nodes (the frontend composes "Files (N)").
    pub name: String,
    /// Full path; for aggregate nodes it is the path of the folder that contains them.
    pub path: String,
    pub kind: NodeKind,
    /// Logical size in bytes.
    #[ts(type = "number")]
    pub size: u64,
    /// Size on disk in bytes.
    #[ts(type = "number")]
    pub disk: u64,
    #[ts(type = "number")]
    pub files: u64,
    #[ts(type = "number")]
    pub dirs: u64,
    pub file_type: Option<FileType>,
    pub ext: Option<String>,
    pub modified: Option<String>,
    pub child_count: u32,
    pub by_type: TypeBreakdown,
}

/// Children of a node, from largest to smallest.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ChildrenOf {
    #[ts(type = "number")]
    pub parent_id: u64,
    pub children: Vec<Node>,
}

/// Disk drive.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Drive {
    /// Letter without colon (e.g. "C").
    pub key: String,
    /// Letter with colon (e.g. "C:").
    pub letter: String,
    pub name: String,
    pub kind: String,
    /// Root path (e.g. "C:\").
    pub path: String,
    #[ts(type = "number")]
    pub total: u64,
    #[ts(type = "number")]
    pub used: u64,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TypeStat {
    pub file_type: FileType,
    #[ts(type = "number")]
    pub size: u64,
    #[ts(type = "number")]
    pub files: u64,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ExtStat {
    pub ext: String,
    pub file_type: FileType,
    #[ts(type = "number")]
    pub size: u64,
    #[ts(type = "number")]
    pub files: u64,
}

/// Space breakdown by file type and by extension.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TypeStats {
    pub types: Vec<TypeStat>,
    pub exts: Vec<ExtStat>,
    #[ts(type = "number")]
    pub total_size: u64,
    #[ts(type = "number")]
    pub total_files: u64,
}

/// Progress of a running scan.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ScanProgress {
    #[ts(type = "number")]
    pub scan_id: u64,
    #[ts(type = "number")]
    pub files: u64,
    #[ts(type = "number")]
    pub dirs: u64,
    #[ts(type = "number")]
    pub bytes: u64,
    pub current_path: String,
    #[ts(type = "number")]
    pub elapsed_ms: u64,
    /// Completed fraction (0..1), if it can be estimated (only for scans of a whole drive).
    pub fraction: Option<f64>,
}

/// Scan completed.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ScanDone {
    #[ts(type = "number")]
    pub scan_id: u64,
    #[ts(type = "number")]
    pub files: u64,
    #[ts(type = "number")]
    pub dirs: u64,
    #[ts(type = "number")]
    pub bytes: u64,
    /// Folders that could not be read (permission denied).
    #[ts(type = "number")]
    pub denied: u64,
    #[ts(type = "number")]
    pub elapsed_ms: u64,
    pub root: Node,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum ScanFailureKind {
    NotFound,
    NotADirectory,
    Denied,
    Cancelled,
    Io,
}

/// Scan not completed: error or cancellation. For a cancellation `files` and `bytes`
/// report how much had been analyzed.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ScanFailed {
    #[ts(type = "number")]
    pub scan_id: u64,
    pub kind: ScanFailureKind,
    pub path: String,
    pub message: String,
    #[ts(type = "number")]
    pub files: u64,
    #[ts(type = "number")]
    pub bytes: u64,
}

/// Where the entry in the Windows registry comes from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "lowercase")]
#[ts(export)]
pub enum AppScope {
    /// Installed for all users (64-bit).
    Machine,
    /// Installed for all users (32-bit).
    Machine32,
    /// Installed for the current user.
    User,
}

/// Installed desktop app, as listed in the Windows registry.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct InstalledApp {
    /// Stable identifier: scope and registry key name.
    pub id: String,
    pub name: String,
    pub version: Option<String>,
    pub publisher: Option<String>,
    /// Install folder, if known.
    pub install_location: Option<String>,
    /// The folder is not declared by the app: it was derived from the icon or the uninstaller.
    pub location_derived: bool,
    /// Several apps declare the same folder (e.g. Office apps): the size is shared.
    pub shared_location: bool,
    /// Size declared by the app in the registry, in bytes (often missing or approximate).
    #[ts(type = "number | null")]
    pub estimated_size: Option<u64>,
    pub install_date: Option<String>,
    pub scope: AppScope,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum SizeStatus {
    Measured,
    /// The folder no longer exists.
    Missing,
    Denied,
    Failed,
}

/// Measured size of an app's folder.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct AppSize {
    pub id: String,
    pub status: SizeStatus,
    pub path: String,
    #[ts(type = "number")]
    pub size: u64,
    #[ts(type = "number")]
    pub disk: u64,
    #[ts(type = "number")]
    pub files: u64,
}

/// End of the app measurement.
#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct AppsMeasureDone {
    #[ts(type = "number")]
    pub measured: u64,
    #[ts(type = "number")]
    pub total: u64,
    pub cancelled: bool,
}
